#import "BTNotificationCoordinator.h"
#import "BTTheme.h"
#include "../../Shared/UI/bt_interaction.h"
@interface BTNotificationLayer : UIView
@property(nonatomic,strong) UIView *card;
@property(nonatomic) BOOL fullscreen;
@end
@implementation BTNotificationLayer
- (UIView *)hitTest:(CGPoint)point withEvent:(UIEvent *)event{if(!self.fullscreen&&!CGRectContainsPoint(self.card.frame,point))return nil;return [super hitTest:point withEvent:event];}
@end
@implementation BTNotificationCoordinator {
    BTNotificationLayer *_layer;UIView *_card;UIImageView *_icon;UILabel *_source,*_title;UITextView *_body;UIButton *_dismiss;
    NSMutableArray *_history,*_queue;NSDictionary *_active;NSTimer *_timer;NSUInteger _generation;
}
- (instancetype)initWithHost:(UIView *)host{if((self=[super init])){_history=[NSMutableArray new];_queue=[NSMutableArray new];_layer=[[BTNotificationLayer alloc] initWithFrame:host.bounds];_layer.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;_layer.hidden=YES;[host addSubview:_layer];_card=[UIView new];_card.layer.cornerRadius=24;_card.backgroundColor=[UIColor colorWithWhite:.14 alpha:.97];_card.layer.borderColor=[UIColor colorWithWhite:1 alpha:.13].CGColor;_card.layer.borderWidth=.5;_layer.card=_card;[_layer addSubview:_card];_icon=[UIImageView new];_icon.image=BTGlyph(@"bell");_icon.tintColor=BTAccent();[_card addSubview:_icon];_source=BTLabel(11,UIFontWeightSemibold);_source.textColor=BTMuted();_title=BTLabel(22,UIFontWeightSemibold);_body=[UITextView new];_body.editable=NO;_body.backgroundColor=UIColor.clearColor;_body.textColor=BTForeground();_body.font=[UIFont systemFontOfSize:13];_body.textContainerInset=UIEdgeInsetsZero;_body.textContainer.lineFragmentPadding=0;[_card addSubview:_source];[_card addSubview:_title];[_card addSubview:_body];_dismiss=BTButton(@"close",@"Dismiss notification",self,@selector(dismiss));[_card addSubview:_dismiss];UISwipeGestureRecognizer *swipe=[[UISwipeGestureRecognizer alloc] initWithTarget:self action:@selector(dismiss)];swipe.direction=UISwipeGestureRecognizerDirectionUp;[_card addGestureRecognizer:swipe];UITapGestureRecognizer *expand=[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(expand)];expand.cancelsTouchesInView=NO;[_card addGestureRecognizer:expand];}return self;}
- (UIView *)view{return _layer;}
- (NSArray *)history{return [_history copy];}
- (NSDate *)expiry:(NSDictionary *)event{NSISO8601DateFormatter *f=[NSISO8601DateFormatter new];f.formatOptions=NSISO8601DateFormatWithInternetDateTime|NSISO8601DateFormatWithFractionalSeconds;NSDate *date=[f dateFromString:BTString(event[@"expiresUtc"],@"")];if(!date){f.formatOptions=NSISO8601DateFormatWithInternetDateTime;date=[f dateFromString:BTString(event[@"expiresUtc"],@"")];}return date;}
- (void)prune{NSIndexSet *expired=[_history indexesOfObjectsPassingTest:^BOOL(NSDictionary *e,NSUInteger i,BOOL *stop){(void)i;(void)stop;return [self expiry:e].timeIntervalSinceNow<=0;}];[_history removeObjectsAtIndexes:expired];}
- (void)accept:(NSDictionary *)event{NSAssert(NSThread.isMainThread,@"Notifications require the main thread");if([self expiry:event].timeIntervalSinceNow<=0)return;[self prune];for(NSDictionary *e in _history)if([e[@"id"] isEqual:event[@"id"]])return;NSMutableDictionary *filtered=[event mutableCopy];if([event[@"sensitive"] boolValue]&&![[NSUserDefaults standardUserDefaults] boolForKey:@"showSensitiveContent"]){filtered[@"title"]=@"Private notification";filtered[@"body"]=@"Open the source on your PC to read it.";}[_history addObject:filtered];while(_history.count>64)[_history removeObjectAtIndex:0];if(self.historyChanged)self.historyChanged(self.history);if([filtered[@"priority"] integerValue]<=0)return;
    if([filtered[@"priority"] integerValue]==3&&_active&&[_active[@"priority"] integerValue]<3){[_timer invalidate];_active=nil;_layer.hidden=YES;}
    if(_queue.count>=8)[_queue removeObjectAtIndex:0];[_queue addObject:filtered];[_queue sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"priority"] compare:a[@"priority"]];}];if(!_active)[self presentNext];
}
- (BOOL)fullscreen:(NSDictionary *)event{(void)event;return NO;}
- (void)presentNext{_generation++;while(_queue.count){NSDictionary *next=_queue.firstObject;[_queue removeObjectAtIndex:0];if([self expiry:next].timeIntervalSinceNow>0){_active=next;break;}}if(!_active){_layer.hidden=YES;if(self.presentationChanged)self.presentationChanged(NO,NO);return;}[self layoutNotice:[self fullscreen:_active]];_layer.hidden=NO;_card.alpha=0;_card.transform=CGAffineTransformMakeTranslation(0,-12);BTAnimate(.22,^{self->_card.alpha=1;self->_card.transform=CGAffineTransformIdentity;},nil);NSTimeInterval duration=MIN([self expiry:_active].timeIntervalSinceNow,_layer.fullscreen?10:([_active[@"priority"] integerValue]>=2?6:3));[_timer invalidate];__weak typeof(self) weak=self;_timer=[NSTimer scheduledTimerWithTimeInterval:MAX(.1,duration) repeats:NO block:^(NSTimer *t){(void)t;[weak dismiss];}];if(self.presentationChanged)self.presentationChanged(_layer.fullscreen,YES);if(_layer.fullscreen)UIAccessibilityPostNotification(UIAccessibilityScreenChangedNotification,_title);else UIAccessibilityPostNotification(UIAccessibilityAnnouncementNotification,_title.text);}
- (void)layoutNotice:(BOOL)fullscreen{(void)fullscreen;CGFloat w=_layer.bounds.size.width,cw=MIN(520,w-40);_layer.fullscreen=NO;_layer.accessibilityViewIsModal=NO;_layer.backgroundColor=UIColor.clearColor;_card.frame=CGRectMake((w-cw)/2,54,cw,88);_icon.frame=CGRectMake(15,26,30,30);_icon.layer.cornerRadius=7;_icon.clipsToBounds=YES;_icon.image=BTThumbnail(_active[@"iconBase64"],64)?:BTGlyph(@"bell");_card.layer.borderColor=[UIColor colorWithWhite:1 alpha:.15].CGColor;_source.frame=CGRectMake(58,8,cw-112,15);_source.numberOfLines=1;_source.text=BTString(_active[@"source"],@"Notification");_title.frame=CGRectMake(58,25,cw-112,22);_title.numberOfLines=1;_title.font=[UIFont systemFontOfSize:15 weight:UIFontWeightSemibold];_title.text=BTString(_active[@"title"],@"");_body.hidden=NO;_body.text=BTString(_active[@"body"],@"");_body.frame=CGRectMake(54,47,cw-105,33);_body.scrollEnabled=YES;_dismiss.frame=CGRectMake(cw-48,5,44,44);}
- (void)expand{}
- (void)dismiss{if(!_active)return;[_timer invalidate];_timer=nil;NSUInteger generation=++_generation;_active=nil;BTAnimate(.16,^{self->_card.alpha=0;},^(BOOL finished){(void)finished;if(generation!=self->_generation)return;self->_layer.hidden=YES;if(self.presentationChanged)self.presentationChanged(NO,NO);[self presentNext];});}
- (NSDictionary *)snapshot{return @{@"visible":@(!_layer.hidden),@"fullscreen":@(_layer.fullscreen&&!_layer.hidden),@"queued":@(_queue.count),@"history":@(_history.count),@"activeId":BTString(_active[@"id"],@"")};}
- (void)dealloc{[_timer invalidate];}
@end
